  'camp.suppressedBouncedNote': 'ഈ വിലാസം നേരത്തെ ബൗൺസ് ആയിരുന്നു അല്ലെങ്കിൽ സ്പാം ആയി അടയാളപ്പെടുത്തിയിരുന്നു, ഭാവിയിലെ എല്ലാ അയക്കലുകളിൽ നിന്നും തടയപ്പെട്ടിരിക്കുന്നു. വീണ്ടും അയച്ചാലും അത് മാറില്ല.',
