  'tpl.design.socialLinksHelp': 'ലളിതമായ, ക്ലിക്ക് ചെയ്യാവുന്ന ടെക്സ്റ്റ് ലിങ്കായി (ഉദാ. "Instagram") കാണിക്കുന്നു — ഒരിക്കലും ചിത്ര ഐക്കണായല്ല, അതിനാൽ ഇത് എല്ലാ ഇമെയിൽ ആപ്പിലും എപ്പോഴും പ്രവർത്തിക്കും. ഓരോന്നിനും അതിന്റേതായ {{key}} ലഭിക്കും — എവിടെയും ചേർക്കാൻ Insert Dynamic Field ഉപയോഗിക്കുക.',
  'tpl.design.unsubscribeText': 'അൺസബ്സ്ക്രൈബ് ലിങ്ക് ടെക്സ്റ്റ്',
  'tpl.design.unsubscribeHelp': 'അൺസബ്സ്ക്രൈബ് ലിങ്ക് വരണം എന്ന് നിങ്ങൾ ആഗ്രഹിക്കുന്നിടത്ത് അതിന്റെ {{key}} ചേർക്കുക. ഇത് ഒഴിവാക്കിയാലും ഓരോ ഇമെയിലിനും യഥാർത്ഥവും പ്രവർത്തിക്കുന്നതുമായ ഒരു അൺസബ്സ്ക്രൈബ് ലിങ്ക് സ്വയമേവ അയക്കപ്പെടുന്നു — അതിനാൽ സ്വീകർത്താക്കൾക്ക് എപ്പോഴും ഒഴിവാകാം.',
