  'dyn.insertField': 'ഡൈനാമിക് ഫീൽഡ് ചേർക്കുക',
  'dyn.manageFields': 'ഡൈനാമിക് ഫീൽഡുകൾ',
  'dyn.managerTitle': 'ഡൈനാമിക് ഫീൽഡുകൾ',
  'dyn.howItWorks': 'സാങ്കേതികമായ ടെക്സ്റ്റ് ഓർത്തിരിക്കുന്നതിന് പകരം "Customer Name" പോലെ ഒരു സൗഹൃദ പേര് എഴുതാൻ ഡൈനാമിക് ഫീൽഡുകൾ അനുവദിക്കുന്നു. ഒരു ക്യാമ്പെയ്ൻ അയക്കുമ്പോൾ, ഇത് സ്വയമേവ ഓരോ സ്വീകർത്താവിന്റെയും യഥാർത്ഥ വിലയായി മാറ്റപ്പെടും — ഉദാഹരണത്തിന്, "Customer Name" നേഹയ്ക്ക് "Neha Kulkarni" ആയും അമിത്തിന് "Amit Shah" ആയും മാറും. സാങ്കേതിക വേരിയബിൾ ഇവിടെ അധിക വിവരമായി മാത്രമേ കാണിക്കുന്നുള്ളൂ; നിങ്ങൾ ഒരിക്കലും അത് സ്വയം ടൈപ്പ് ചെയ്യേണ്ടതില്ല.',
