  'dyn.customTitle': 'നിങ്ങളുടെ കസ്റ്റം ഫീൽഡുകൾ',
  'dyn.customHelp': 'മുകളിൽ ലിസ്റ്റ് ചെയ്യാത്ത എന്തിനും (ഉദാ. "Order Number") സ്വന്തം ഫീൽഡ് ചേർക്കുക. നിങ്ങളുടെ ഡാറ്റയിൽ ആ വില ഉൾപ്പെടുന്നതുവരെ ഇത് സുരക്ഷിതമായി ശൂന്യമായി ചേർക്കപ്പെടും.',
