  'auth.sentNote': 'ഈ ലിങ്ക് 1 മണിക്കൂർ പ്രവർത്തിക്കും, ഒരു തവണ മാത്രം ഉപയോഗിക്കാം. ആ വിലാസം നിലവിലുണ്ടോ എന്ന് ഞങ്ങൾ പറയാറില്ല — അത് പറഞ്ഞാൽ ഇവിടെ ആർക്കാണ് അക്കൗണ്ട് ഉള്ളതെന്ന് ഒരു അപരിചിതന് അറിയാം.',
