  'sysmail.intro': 'ഇവ ക്യാമ്പെയ്‌നുകളല്ല. ഓരോന്നും ഒരു ഇവന്റ് സംഭവിക്കുമ്പോൾ പ്രവർത്തിക്കുന്നു, ഡിസൈൻ ഇതിനകം എഴുതിയിട്ടുണ്ട്. ബാക്കെൻഡ് ബിൽഡ് ചെയ്യുമ്പോൾ, ഓരോ ഇവന്റിനും ഒരു വരി മാത്രം മതി — വിഷയവും HTML-ഉം ഇവിടെ നിന്ന് വരും.',
  'sysmail.list': 'എല്ലാ സിസ്റ്റം ഇമെയിലുകളും',
  'sysmail.listSub': 'പ്രിവ്യൂ ചെയ്യാനോ എഡിറ്റ് ചെയ്യാനോ ഒന്ന് തിരഞ്ഞെടുക്കുക',
  'sysmail.group': 'ഗ്രൂപ്പ്',
  'sysmail.language': 'ഭാഷ',
  'sysmail.fallbackNote': 'ഇതുവരെ {language} പതിപ്പ് സേവ് ചെയ്തിട്ടില്ല — താഴെ ഇംഗ്ലീഷ് ഉള്ളടക്കം കാണിക്കുന്നു. ഒന്ന് ഉണ്ടാക്കാൻ എഡിറ്റ് ചെയ്ത് സേവ് ചെയ്യുക.',
  'sysmail.removeTranslation': 'ഈ ഭാഷാ പതിപ്പ് നീക്കം ചെയ്യുക',
