  'sysmail.previewNote': 'പ്രിവ്യൂ വേരിയബിളുകൾ ഉദാഹരണ വിലകൾ കൊണ്ട് പൂരിപ്പിക്കുന്നു, അതിനാൽ നിങ്ങൾക്ക് ഇത് ഒരു യഥാർത്ഥ ഇമെയിലായി വായിക്കാം.',
  'sysmail.variables': 'നിങ്ങൾക്ക് ഉപയോഗിക്കാവുന്ന വേരിയബിളുകൾ',
  'sysmail.variablesHelp': 'വിഷയത്തിലോ HTML-ലോ ഒരു വേരിയബിൾ എഴുതുക, അയക്കുമ്പോൾ യഥാർത്ഥ വില അതിന്റെ സ്ഥാനത്ത് വരും.',
  'sysmail.reset': 'യഥാർത്ഥത്തിലേക്ക് തിരികെ സെറ്റ് ചെയ്യുക',
