  'sysmail.optionalNote': 'നിങ്ങളുടെ ടീമിന് ഇത് അധിക ഇമെയിലാണെങ്കിൽ ഇത് ഓഫ് ചെയ്യാം.',
  'sysmail.forDevs': 'ബാക്കെൻഡ് ഇത് എങ്ങനെ അയയ്ക്കുന്നു',
  'sysmail.adminOnly': 'ഈ പേജ് ഒരു സൂപ്പർ അഡ്മിന് മാത്രമേ തുറക്കാൻ കഴിയൂ.',
  'sysmail.statusOn': 'എനേബിൾ ചെയ്തു',
  'sysmail.statusOff': 'ഡിസേബിൾ ചെയ്തു',
  'sysmail.sendTest': 'ടെസ്റ്റ് അയയ്ക്കുക',
  'sysmail.testNote': 'നിങ്ങളുടെ സ്വന്തം ഇമെയിലിലേക്ക് ഒരു സാമ്പിൾ അയക്കുന്നു, അതിനാൽ ഇത് എങ്ങനെ കാണപ്പെടുന്നു എന്ന് കാണാം — മുകളിലുള്ള സ്വിച്ച് ഓഫ് ആയിരിക്കുമ്പോഴും ഇത് പ്രവർത്തിക്കും, സ്വയമേവയുള്ള അയയ്ക്കൽ ഓണാക്കില്ല.',
  'sysmail.testSentTo': '{email}-ലേക്ക് ടെസ്റ്റ് അയച്ചു',

  'help.sysmail.1': 'ആപ്പ് സ്വയം അയക്കുന്ന ഓരോ ഇമെയിലും, അത് പ്രവർത്തിപ്പിക്കുന്ന ഇവന്റോടെ ഇവിടെ ലിസ്റ്റ് ചെയ്തിരിക്കുന്നു.',
  'help.sysmail.2': 'ഏത് ടെംപ്ലേറ്റും പോലെ വിഷയവും HTML-ഉം എഡിറ്റ് ചെയ്യുക. പാസ്‌വേഡ് ഇമെയിലുകൾ ഓഫ് ചെയ്യാൻ കഴിയില്ല.',

  'theme.title': 'രൂപവും ഭാവവും',
  'theme.subtitle': 'പകലോ രാത്രിയോ, ആപ്പ് നിർമ്മിച്ചിരിക്കുന്ന നിറവും.',
  'theme.mode': 'പകൽ / രാത്രി',
  'theme.light': 'പകൽ',
  'theme.dark': 'രാത്രി',
  'theme.system': 'എന്റെ കമ്പ്യൂട്ടർ പോലെ',
  'theme.colour': 'പ്രധാന നിറം',
  'theme.help': 'നിങ്ങളുടെ തിരഞ്ഞെടുപ്പ് ഈ ഡിവൈസിൽ മാത്രമേ സേവ് ചെയ്യൂ. മറ്റുള്ളവർ കാണുന്നത് മാറില്ല.',
  'theme.indigo': 'ഇൻഡിഗോ',
  'theme.blue': 'നീല',
  'theme.teal': 'ടീൽ',
  'theme.green': 'പച്ച',
  'theme.amber': 'ആമ്പർ',
  'theme.rose': 'റോസ്',
  'theme.purple': 'പർപ്പിൾ',
  'theme.slate': 'സ്ലേറ്റ്',
  'theme.brandNote': 'ആപ്പിന്റെ പേര്, ടാഗ്‌ലൈൻ, ലോഗോ എല്ലാം ഒരു ഫയലിൽ നിന്നാണ് വരുന്നത് — src/config/appConfig.js. അവിടെ ഒരു തവണ മാറ്റുക, സൈഡ്ബാർ, ലോഗിൻ പേജ്, ബ്രൗസർ ടാബ്, പ്രിവ്യൂ പേജുകൾ എല്ലാം അതിനെ പിന്തുടരും.',
