  'info.subjectTip': 'വിഷയം ഏകദേശം 50 അക്ഷരങ്ങൾക്കുള്ളിൽ വയ്ക്കുക. നീണ്ട വിഷയങ്ങൾ ഫോണുകളിൽ മുറിഞ്ഞുപോകും.',

