  'send.delayLabel': 'ബാച്ചുകൾക്കിടയിലെ കാത്തിരിപ്പ്: {minutes} മിനിറ്റ്',
  'send.delayHelp': 'ഒരു ചെറിയ കാത്തിരിപ്പ് നിങ്ങളെ പ്രൊവൈഡറിന്റെ പ്രസിദ്ധീകരിച്ച അയയ്ക്കൽ പരിധികൾക്കുള്ളിൽ നിലനിർത്തുന്നു. ഞങ്ങൾ അവയെ കടക്കാൻ ഒരിക്കലും ശ്രമിക്കാറില്ല.',
  'send.estimateUnderMinute': 'ഒരു മിനിറ്റിൽ താഴെ',
  'send.estimateMinutes': '{minutes} മിനിറ്റ്',
