  'send.estimateSameDay': '≈ {batches} ബാച്ചുകളിലായി {duration} — എല്ലാം ഇന്ന് തന്നെ.',
  'send.estimateQuotaLimited': '≈ {days} ദിവസം — {account}-ന് ദിവസം {limit} മാത്രമേ അയക്കാൻ കഴിയൂ, അതിനാൽ അയയ്ക്കൽ ഓരോ ദിവസവും സ്വയമേവ നിർത്തിവെക്കുകയും തുടരുകയും ചെയ്യും. ബാച്ചുകൾക്കിടയിൽ യഥാർത്ഥ കാത്തിരിപ്പ് സമയം ഏകദേശം {duration}.',
  'send.estimateSampleLabel': 'എത്ര സ്വീകർത്താക്കൾക്കുള്ള കണക്ക്?',
  'send.estimateAccountNote': 'ഇത് ഒരു ഏകദേശ കണക്കാണ് (ബാച്ച് വലിപ്പം × കാത്തിരിപ്പ് സമയം മാത്രം). യഥാർത്ഥ എണ്ണം ഏത് ഇമെയിൽ അക്കൗണ്ട് ഇത് അയക്കുന്നു, ആ അക്കൗണ്ടിന്റെ ദിവസേനയുള്ള പരിധി എന്നിവയെ ആശ്രയിച്ചിരിക്കുന്നു — കൃത്യമായ കണക്കിന് ക്യാമ്പെയ്ൻ വിസാർഡിൽ ഒരു യഥാർത്ഥ ഓഡിയൻസ് തിരഞ്ഞെടുക്കുക.',
  'send.openTracking': 'ഓപ്പൺ ട്രാക്കിംഗ്',
  'send.openTrackingDesc': 'ഓപ്പണുകൾ കണക്കാക്കാൻ ഒരു ചെറിയ കണ്ണിൽ കാണാത്ത ചിത്രം ചേർക്കുന്നു. ഫലങ്ങൾ ഒരു ഏകദേശക്കണക്കാണ് — ചില മെയിൽ ആപ്പുകൾ ചിത്രം തടയുന്നു, പ്രൈവസി പ്രോക്സികൾ ഒരിക്കലും സംഭവിക്കാത്ത ഒരു ഓപ്പൺ എണ്ണിയേക്കാം.',
  'send.clickTracking': 'ക്ലിക്ക് ട്രാക്കിംഗ്',
  'send.clickTrackingDesc': 'ക്ലിക്കുകൾ എണ്ണാൻ ഈ ക്യാമ്പെയ്‌നിലെ ലിങ്കുകൾ വീണ്ടും എഴുതുന്നു. ഡിഫോൾട്ടായി ഓഫാണ് — ഓരോ ക്യാമ്പെയ്‌നിനും നിങ്ങൾ ഇത് ഓണാക്കുന്നു.',
  'send.subscribeButton': 'Subscribe ബട്ടൺ',
  'send.subscribeTitle': 'ഈ ഇമെയിലിൽ ഒരു Subscribe ബട്ടൺ ചേർക്കുക',
  'send.subscribeDesc': 'ചില ഇമെയിലുകൾ ഇതുവരെ നിങ്ങളുടെ ലിസ്റ്റിൽ ഇല്ലാത്ത ആളുകൾക്കും പോകുന്നു. ഒരു Subscribe ബട്ടൺ അവരെ കൂടുതൽ ചോദിക്കാൻ അനുവദിക്കുന്നു. അത് അമർത്തുന്ന ആരും നിങ്ങളുടെ Subscribers പേജിൽ, ഈ ക്യാമ്പെയ്‌നിന്റെ പേരോടൊപ്പം എത്തും — അതിനാൽ അവർ എവിടെ നിന്ന് വന്നു എന്ന് നിങ്ങൾക്ക് എപ്പോഴും അറിയാം.',
  'send.subscribeNote': 'നിങ്ങളുടെ HTML-ൽ എവിടെയും {{subscribe_url}} ഇടുക, അത് സബ്സ്ക്രൈബ് ലിങ്കായി മാറും. നിങ്ങൾ ഇത് ഒഴിവാക്കിയാൽ, ഫൂട്ടറിന് മുകളിൽ ഒരു ചെറിയ ബട്ടൺ ഞങ്ങൾ നിങ്ങൾക്കായി ചേർക്കും.',
  'send.whenTitle': 'ഇത് എപ്പോൾ പോകണം?',
  'send.now': 'ഇപ്പോൾ അയയ്ക്കുക',
  'send.nowDesc': 'നിങ്ങൾ സ്ഥിരീകരിച്ച ഉടൻ അയയ്ക്കൽ തുടങ്ങും.',
  'send.later': 'പിന്നീടേക്ക് ഷെഡ്യൂൾ ചെയ്യുക',
  'send.laterDesc': 'ഒരു തീയതിയും സമയവും തിരഞ്ഞെടുക്കുക. ഞങ്ങൾ ഇത് നിങ്ങൾക്കായി ക്യൂവിൽ വയ്ക്കും.',
  'send.dateTime': 'തീയതിയും സമയവും',
  'send.queueNote': 'അയയ്ക്കൽ ഞങ്ങളുടെ സെർവർ ക്യൂവിൽ നടക്കുന്നു. നിങ്ങൾക്ക് ഈ ടാബോ ലാപ്ടോപ്പോ അടയ്ക്കാം — ക്യാമ്പെയ്ൻ തുടരും, എപ്പോൾ വേണമെങ്കിലും നിർത്തിവെക്കാം.',

