  'acc.connectedNote': 'ഒരു സെർവർ സെറ്റിംഗും ഞങ്ങൾ നിങ്ങൾക്ക് ഒരിക്കലും കാണിച്ചില്ല — ഒരിക്കലും കാണിക്കില്ല. സൈൻ ഇൻ പ്രൊവൈഡറുമായി നേരിട്ടാണ് നടന്നത്.',
  'acc.goToAccounts': 'ഇമെയിൽ അക്കൗണ്ടുകളിലേക്ക് പോകുക',
  'acc.tokenNote': 'Google, Microsoft എന്നിവയിൽ നിങ്ങൾ അവരുടെ സ്വന്തം പേജിൽ സൈൻ ഇൻ ചെയ്യുന്നു. {app} നിങ്ങളുടെ പാസ്‌വേഡ് ഒരിക്കലും കാണുകയോ സൂക്ഷിക്കുകയോ ചെയ്യില്ല — ഞങ്ങളുടെ സെർവറിൽ എൻക്രിപ്റ്റ് ചെയ്ത ഒരു ടോക്കൺ മാത്രം.',
  'acc.provider.google': 'Google ഉപയോഗിച്ച് ഒരു ക്ലിക്കിൽ സൈൻ ഇൻ. പൂരിപ്പിക്കാൻ സെറ്റിംഗ്സ് ഇല്ല.',
  'acc.provider.microsoft': 'നിങ്ങളുടെ Microsoft ജോലി അല്ലെങ്കിൽ വ്യക്തിഗത അക്കൗണ്ട് ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുക.',
  'acc.provider.sendgrid': 'ഉയർന്ന അളവിൽ അയക്കാൻ ഒരു API കീ ഉപയോഗിച്ച് കണക്ട് ചെയ്യുക.',
  'acc.provider.mailgun': 'നിങ്ങളുടെ Mailgun ഡൊമെയ്‌നും API കീയും കണക്ട് ചെയ്യുക.',
  'acc.provider.ses': 'നിങ്ങളുടെ AWS SES റീജിയനും ക്രെഡൻഷ്യലും ഉപയോഗിക്കുക.',
  'acc.provider.smtp': 'മറ്റേതെങ്കിലും പ്രൊവൈഡർ. ഞങ്ങൾ ഒരു ഫീൽഡ് വീതം നിങ്ങളെ നയിക്കും.',
  'acc.credTitle': 'നിങ്ങളുടെ ക്രെഡൻഷ്യലുകൾ എങ്ങനെ സൂക്ഷിക്കുന്നു',
  'acc.credSub': 'ചെറിയ പതിപ്പ്, ലളിതമായ വാക്കുകളിൽ',
  'acc.credHidden': 'ബ്രൗസറിൽ ഒരിക്കലും കാണിക്കില്ല.',
  'acc.credHiddenText': 'പാസ്‌വേഡുകൾ, API കീകൾ, OAuth ടോക്കണുകൾ എന്നിവ സെർവറിൽ തന്നെ നിലനിൽക്കുന്നു. ഈ സ്ക്രീൻ ഒരു കണക്ഷൻ സ്റ്റാറ്റസ് മാത്രമേ ഒരിക്കലും കാണൂ.',
  'acc.credEncrypted': 'സൂക്ഷിക്കുമ്പോൾ എൻക്രിപ്റ്റ് ചെയ്തത്.',
  'acc.credEncryptedText': 'AES-256 കൊണ്ട് സൂക്ഷിച്ചത്, കീ ഒരു സീക്രട്ട്സ് മാനേജറിൽ — ഒരിക്കലും കോഡിനുള്ളിൽ അല്ല.',
  'acc.credRefreshed': 'നിങ്ങൾക്കായി പുതുക്കുന്നു.',
  'acc.credRefreshedText': 'കാലാവധി കഴിഞ്ഞ OAuth ടോക്കണുകൾ സെർവറിൽ പുതുക്കുന്നു. ഓരോ ആഴ്ചയും വീണ്ടും സൈൻ ഇൻ ചെയ്യേണ്ടതില്ല.',
  'acc.limitNote': 'ഓരോ പ്രൊവൈഡറിനും അതിന്റേതായ ദിവസേനയുള്ള അയയ്ക്കൽ പരിധിയുണ്ട്. {app} ആ പരിധികൾക്കുള്ളിൽ നിൽക്കുന്നു, അവയെ കടക്കുന്നതിന് പകരം വേഗത കുറയ്ക്കുന്നു.',
  'acc.testTitle': 'ഒരു ടെസ്റ്റ് ഇമെയിൽ അയയ്ക്കുക',
  'acc.testSend': 'ടെസ്റ്റ് അയയ്ക്കുക',
  'acc.testBody': '{email}-ൽ നിന്ന് ഒരു ചെറിയ ടെസ്റ്റ് സന്ദേശം അയക്കും, അതിനാൽ അത് എത്തുന്നുണ്ടോ എന്ന് നിങ്ങൾക്ക് പരിശോധിക്കാം.',
  'acc.testTo': 'ഇതിലേക്ക് അയയ്ക്കുക',
  'acc.testSpam': 'ഒരു മിനിറ്റിനുള്ളിൽ എത്തുന്നില്ലെങ്കിൽ നിങ്ങളുടെ സ്പാം ഫോൾഡറും പരിശോധിക്കുക.',

