  'smtp.email.help': 'നിങ്ങളുടെ ഇമെയിലുകൾ അയക്കുന്ന വിലാസം ഇതാണ്.',
  'smtp.host.title': 'നിങ്ങളുടെ ഔട്ട്ഗോയിംഗ് സെർവർ (SMTP ഹോസ്റ്റ്) എന്താണ്?',
  'smtp.host.help': 'നിങ്ങളുടെ ഇമെയിൽ പ്രൊവൈഡർ ഇത് അവരുടെ ഹെൽപ്പ് പേജുകളിൽ ലിസ്റ്റ് ചെയ്യുന്നു. സാധാരണയായി ഇത് smtp.yourprovider.com പോലെ കാണപ്പെടും.',
