  'smtp.security.title': 'നിങ്ങളുടെ സെർവർ ഏത് സുരക്ഷയാണ് ഉപയോഗിക്കുന്നത്?',
  'smtp.security.help': 'SSL, TLS രണ്ടും നിങ്ങളുടെ ഇമെയിൽ യാത്ര ചെയ്യുമ്പോൾ എൻക്രിപ്റ്റ് ചെയ്യുന്നു. "None" സുരക്ഷിതമല്ല, മിക്ക പ്രൊവൈഡർമാരും ഇനി ഇത് അനുവദിക്കുന്നില്ല.',
