  'smtp.login.title': 'നിങ്ങളുടെ യൂസർനെയിമും പാസ്‌വേഡും',
  'smtp.login.help': 'പല പ്രൊവൈഡർമാർക്കും സാധാരണ പാസ്‌വേഡിന് പകരം ഒരു "app password" വേണം. നിങ്ങളുടെ ഇമെയിൽ അക്കൗണ്ട് സുരക്ഷാ സെറ്റിംഗ്സിൽ App Passwords നോക്കുക.',
