  'smtp.login.note': 'Gmail, Outlook ഉപയോക്താക്കൾ: നിങ്ങൾക്ക് സാധാരണയായി ഈ സ്ക്രീൻ ഒട്ടും വേണ്ട. തിരികെ പോയി ഒരു-ക്ലിക്ക് സൈൻ-ഇൻ ഉപയോഗിക്കുക — ഇത് സുരക്ഷിതവും വേഗതയേറിയതുമാണ്.',
  'smtp.test.title': 'ഇത് പ്രവർത്തിക്കുന്നു എന്ന് നമുക്ക് പരിശോധിക്കാം',
  'smtp.test.help': 'ഞങ്ങൾ ഒരു ചെറിയ ടെസ്റ്റ് ഇമെയിൽ അയയ്ക്കും. ഇത് വിജയിക്കുന്നതുവരെ ഒന്നും സേവ് ചെയ്യില്ല.',
  'smtp.test.note': 'പോർട്ട് {port}-ൽ {host} ഉപയോഗിച്ച് {email}-ലേക്ക് ഞങ്ങൾ ഒരു ടെസ്റ്റ് സന്ദേശം അയക്കും.',
