  'set.emailLanguage': 'ഇഷ്ടപ്പെട്ട ഇമെയിൽ ഭാഷ',
  'set.emailLanguageHelp': 'നിങ്ങൾക്ക് ലഭിക്കുന്ന ഓട്ടോമാറ്റിക് ഇമെയിലുകൾ — പാസ്‌വേഡ് റീസെറ്റുകൾ, ക്ഷണങ്ങൾ — ഈ ഭാഷയിൽ എത്തും. ഇത് മുകളിലുള്ള Language ടാബിൽ നിന്ന് വേറെയാണ്, അത് സ്ക്രീനിൽ നിങ്ങൾ കാണുന്നത് മാത്രം മാറ്റുന്നു.',
