  'set.accountsNote': 'അക്കൗണ്ടുകൾ അവയുടെ സ്വന്തം പേജിൽ കൈകാര്യം ചെയ്യുന്നു, അവിടെ ഓരോന്നും ടെസ്റ്റ് ചെയ്യാം അല്ലെങ്കിൽ ഡിസ്കണക്ട് ചെയ്യാം.',
  'set.openAccounts': 'ഇമെയിൽ അക്കൗണ്ടുകൾ തുറക്കുക',
  'set.addLanguageNote': 'വേറൊരു ഭാഷ വേണോ? src/i18n/locales/en.js കോപ്പി ചെയ്ത്, വിലകൾ വിവർത്തനം ചെയ്ത്, src/i18n/languages.js-ൽ ഒരു വരി ചേർക്കുക. നിങ്ങൾ ഒഴിവാക്കുന്ന ഏത് കീയും ഇംഗ്ലീഷിലേക്ക് തിരികെ പോകും, അതിനാൽ പകുതി പൂർത്തിയായ ഒരു വിവർത്തനം ഒരു സ്ക്രീനും ഒരിക്കലും തകർക്കില്ല.',
  'set.sendingTitle': 'അയയ്ക്കൽ സെറ്റിംഗ്സ്',
  'set.sendingSub': 'ഓരോ പുതിയ ക്യാമ്പെയ്‌നും ഉപയോഗിക്കുന്ന ഡിഫോൾട്ടുകൾ',
  'set.defaultBatch': 'ഡിഫോൾട്ട് ബാച്ച് വലിപ്പം',
  'set.minutesBetween': 'ബാച്ചുകൾക്കിടയിലെ മിനിറ്റുകൾ',
  'set.retryTitle': 'പരാജയപ്പെട്ട ഇമെയിലുകൾ ഒരു തവണ വീണ്ടും ശ്രമിക്കുക',
  'set.retryDesc': 'ഒരു താൽക്കാലിക പ്രൊവൈഡർ എറർ 15 മിനിറ്റിന് ശേഷം വീണ്ടും ശ്രമിക്കും. ഹാർഡ് ബൗൺസുകൾ ഒരിക്കലും വീണ്ടും ശ്രമിക്കില്ല.',
  'set.quietTitle': 'നിശബ്ദ സമയം (രാത്രി 9 – രാവിലെ 8) പാലിക്കുക',
  'set.quietDesc': 'ക്യൂവിലുള്ള ഇമെയിലുകൾ സ്വീകർത്താവിന്റെ ടൈം സോണിൽ രാവിലെ വരെ കാത്തിരിക്കും.',
  'set.sendingNote': 'ഇവിടെ നിങ്ങൾ സെറ്റ് ചെയ്യുന്ന ബാച്ച് വലിപ്പവും കാത്തിരിപ്പും ഓരോ പുതിയ ക്യാമ്പെയ്‌നിന്റെയും തുടക്കമാകും — വിസാർഡിൽ ഓരോ ക്യാമ്പെയ്‌നിനും ഇപ്പോഴും അവ മാറ്റാം. റീട്രൈ ഓരോ ക്യാമ്പെയ്‌നിനും സ്വയമേവ ബാധകമാകുന്നു. Quiet hours ഒരു മുൻഗണനയായി സേവ് ചെയ്യുന്നു; അയയ്ക്കൽ എഞ്ചിൻ ഇതുവരെ അതനുസരിച്ച് പ്രവർത്തിക്കുന്നില്ല.',
  'set.trackingTitle': 'ട്രാക്കിംഗ് സെറ്റിംഗ്സ്',
  'set.trackingSub': 'ഞങ്ങൾ എന്ത് രേഖപ്പെടുത്തുന്നു, എന്ത് ചെയ്യുന്നില്ല',
  'set.openDefaultTitle': 'ഡിഫോൾട്ടായി ഓപ്പൺ ട്രാക്കിംഗ് ഓണ്',
  'set.openDefaultDesc': 'ഓപ്പണുകൾ കണക്കാക്കാൻ ഒരു കണ്ണിൽ കാണാത്ത ചിത്രം ചേർക്കുന്നു. ഓരോ ക്യാമ്പെയ്‌നിനും ഇപ്പോഴും ഇത് ഓഫ് ചെയ്യാം.',
  'set.clickDefaultTitle': 'ഡിഫോൾട്ടായി ക്ലിക്ക് ട്രാക്കിംഗ് ഓണ്',
  'set.clickDefaultDesc': 'ക്ലിക്കുകൾ എണ്ണാൻ ലിങ്കുകൾ വീണ്ടും എഴുതുന്നു. ലളിതമായ ലിങ്കുകൾ ഇഷ്ടമെങ്കിൽ ഇത് ഓഫ് ചെയ്യുക.',
  'set.deviceTitle': 'ഡിവൈസ് തരം രേഖപ്പെടുത്തുക',
  'set.deviceDesc': 'റോ ബ്രൗസർ/മെയിൽ-ആപ്പ് സ്ട്രിംഗ് ഓരോ ഓപ്പണിനും ക്ലിക്കിനും ഇതിനകം എപ്പോഴും സൂക്ഷിക്കുന്നു — ഈ സ്വിച്ച് ഇതുവരെ അത് മാറ്റുന്നില്ല.',
  'set.locationTitle': 'ഏകദേശ സ്ഥാനം രേഖപ്പെടുത്തുക',
  'set.locationDesc': 'IP വിലാസം ഇതിനകം എപ്പോഴും സൂക്ഷിക്കുന്നു — ഈ സ്വിച്ച് ഇതുവരെ ഒരു രാജ്യപ്പേര് ഓണോ ഓഫോ ചെയ്യുന്നില്ല, കാരണം ഇതുവരെ ഒരു ലുക്കപ്പ് സ്റ്റെപ്പ് ഇല്ല.',
  'set.openEstimateNote': 'ഓപ്പൺ എണ്ണം എപ്പോഴും ഒരു ഏകദേശക്കണക്കാണ്. ചിത്രം തടയൽ യഥാർത്ഥ ഓപ്പണുകൾ മറയ്ക്കുന്നു, പ്രൈവസി പ്രോക്സികൾ ഒരിക്കലും സംഭവിക്കാത്ത ഓപ്പണുകൾ ഉണ്ടാക്കുന്നു. ഇക്കാരണത്താൽ ഞങ്ങൾ ഓരോ ഓപ്പണിനെയും "Open detected" എന്ന് ലേബൽ ചെയ്യുന്നു.',
  'set.trackingNote': 'ഓപ്പൺ, ക്ലിക്ക് ട്രാക്കിംഗ് ഡിഫോൾട്ടുകൾ ശരിക്കും ഓരോ പുതിയ ക്യാമ്പെയ്‌നിനും ബാധകമാണ് (ഓരോ ക്യാമ്പെയ്‌നിനും ഇപ്പോഴും ഇത് മറികടക്കാം). Device, Location ഇപ്പോൾ ഒരു മുൻഗണന മാത്രമായി സേവ് ചെയ്യുന്നു — ഈ രണ്ട് സ്വിച്ചുകൾ എന്തുതന്നെയായാലും റോ യൂസർ-ഏജന്റും IP-യും ഓരോ ഓപ്പണിലും രേഖപ്പെടുത്തുന്നു.',
  'set.templateOptions': 'ടെംപ്ലേറ്റ് ഓപ്ഷനുകൾ',
  'set.templateOptionsSub': 'ഏത് ടെംപ്ലേറ്റ് നിർമ്മാണ രീതികൾ ലഭ്യമാണ് എന്ന് തിരഞ്ഞെടുക്കുക',
  'set.templateOptionsNote': 'ഒരു രീതി ഓഫ് ചെയ്യുന്നത് അത് മറയ്ക്കുക മാത്രമേ ചെയ്യൂ — പുതിയ ടെംപ്ലേറ്റുകളും അവ ലിസ്റ്റ് ചെയ്യുന്ന എല്ലായിടത്തും — ഒന്നും ഒരിക്കലും ഇല്ലാതാക്കില്ല. ആ തരത്തിലുള്ള നിലവിലുള്ള ടെംപ്ലേറ്റുകൾ സുരക്ഷിതമായി തുടരുകയും തിരികെ ഓണാക്കിയ ഉടൻ വീണ്ടും കാണിക്കുകയും ചെയ്യും.',
  'set.tplSrcCustomTitle': 'കസ്റ്റം എഡിറ്റർ',
  'set.tplSrcCustomDesc': 'Design + Code എഡിറ്റർ ഉപയോഗിച്ച് ടെംപ്ലേറ്റുകൾ ഉണ്ടാക്കുക.',
  'set.tplSrcUploadTitle': 'HTML അപ്‌ലോഡ്',
