  'set.tplSrcBuilderTitle': 'ഡ്രാഗ് & ഡ്രോപ്പ് ബിൽഡർ',
  'set.tplSrcBuilderDesc': 'ഡ്രാഗ്-ആൻഡ്-ഡ്രോപ്പ് ബ്ലോക്കുകൾ ഉപയോഗിച്ച് വിഷ്വലായി ടെംപ്ലേറ്റുകൾ ഉണ്ടാക്കുക.',
  'set.contactsTitle': 'കോൺടാക്റ്റ് സെറ്റിംഗ്സ്',
  'set.contactsSub': 'പുതിയ കോൺടാക്റ്റുകൾ എങ്ങനെ കൈകാര്യം ചെയ്യുന്നു',
  'set.dedupeTitle': 'ഇംപോർട്ട് ചെയ്യുമ്പോൾ ഡ്യൂപ്ലിക്കേറ്റുകൾ നീക്കം ചെയ്യുക',
  'set.dedupeDesc': 'ആദ്യ കോപ്പി സൂക്ഷിക്കുന്നു, ബാക്കിയുള്ളവ ഒഴിവാക്കുന്നു. ശുപാർശ ചെയ്യുന്നത്.',
