  'set.customFields': 'കസ്റ്റം ഫീൽഡുകൾ',
  'set.customFieldsHelp': 'കോമ കൊണ്ട് വേർതിരിക്കുക. ഓരോന്നും {{city}} പോലെ ഒരു വേരിയബിൾ ആകും.',
  'set.contactsNote': 'ഇംപോർട്ട് ചെയ്യുമ്പോൾ ഡ്യൂപ്ലിക്കേറ്റുകൾ നീക്കം ചെയ്യുന്നത് ഇതിനകം എപ്പോഴും സംഭവിക്കുന്നു — ഇത് ഓപ്ഷണൽ അല്ല. മറ്റ് രണ്ടും ഒരു മുൻഗണനയായി സേവ് ചെയ്യുന്നു; ഇംപോർട്ട് സ്ക്രീൻ ഇതുവരെ കൺസെന്റ് നിർബന്ധമാക്കുന്നില്ല, കസ്റ്റം ഫീൽഡുകൾ ടെംപ്ലേറ്റുകളിൽ മെർജ് വേരിയബിളുകളായി ഇതുവരെ ലഭ്യമല്ല.',
