  'set.unsubGlobalTitle': 'അൺസബ്സ്ക്രൈബുകൾ ആഗോളമായി ബാധകമാക്കുക',
  'set.unsubGlobalDesc': 'ഓഫ് (ശുപാർശ ചെയ്യുന്നത്): ഒരു അയക്കുന്ന അക്കൗണ്ടിൽ നിന്ന് അൺസബ്സ്ക്രൈബ് ചെയ്യുന്നത് ആ അക്കൗണ്ടിൽ നിന്നുള്ള ഭാവി ഇമെയിലുകൾ മാത്രം തടയുന്നു — ഈ വർക്ക്സ്പേസിലെ മറ്റ് അക്കൗണ്ടുകൾക്ക് ഇപ്പോഴും അവർക്ക് ഇമെയിൽ ചെയ്യാം. ഓണ്: ഒരു അൺസബ്സ്ക്രൈബ് എല്ലാ അയക്കുന്ന അക്കൗണ്ടും തടയുന്നു.',
  'set.unsubNote': 'അൺസബ്സ്ക്രൈബ് ചെയ്ത ആളുകൾ ആ അയക്കുന്ന അക്കൗണ്ടിന്റെ സപ്രഷൻ ലിസ്റ്റിലേക്ക് പോകുന്നു, ആ അക്കൗണ്ടിന്റെ ഭാവി ക്യാമ്പെയ്‌നുകളിൽ നിന്ന് സ്വയമേവ നീക്കം ചെയ്യപ്പെടും.',
