  'set.storageDisconnectConfirmText': 'ഇത് സേവ് ചെയ്ത ക്രെഡൻഷ്യലുകൾ മാത്രമേ നീക്കം ചെയ്യൂ — ഇതിനകം അപ്‌ലോഡ് ചെയ്ത ചിത്രങ്ങൾ ഒരിക്കലും ഇല്ലാതാക്കില്ല. നിങ്ങൾ വീണ്ടും സ്റ്റോറേജ് കണക്ട് ചെയ്യുന്നതുവരെ പുതിയ അപ്‌ലോഡുകൾ ഈ ആപ്പിന്റെ സ്വന്തം ഡാറ്റാബേസിലേക്ക് തിരികെ പോകും.',

