  'set.imageStorageSub': 'പുതിയ ചിത്ര അപ്‌ലോഡുകൾ എവിടെ പോകാം എന്ന് തിരഞ്ഞെടുക്കുക',
  'set.imgStoreDbTitle': 'DB ഇമേജ് സ്റ്റോറേജ്',
  'set.imgStoreDbDesc': 'പുതിയ അപ്‌ലോഡ് ചെയ്ത ചിത്രങ്ങൾ ഈ ആപ്പിന്റെ സ്വന്തം ഡാറ്റാബേസിൽ നേരിട്ട് സൂക്ഷിക്കുക.',
  'set.imgStoreExternalTitle': 'എക്സ്റ്റേണൽ ഇമേജ് സ്റ്റോറേജ്',
  'set.imgStoreExternalDesc': 'പുതിയ അപ്‌ലോഡുകൾക്ക് നിങ്ങളുടെ കണക്ട് ചെയ്ത എക്സ്റ്റേണൽ സ്റ്റോറേജ് പ്രൊവൈഡർ (മുകളിൽ, Storage-ന് കീഴിൽ കോൺഫിഗർ ചെയ്തത്) ഉപയോഗിക്കുക.',
  'set.imageStorageNote': 'രണ്ടും ഓഫ് ചെയ്യുന്നത് ഒരു വ്യക്തമായ സന്ദേശത്തോടെ പുതിയ അപ്‌ലോഡുകൾ തടയും — നിലവിലുള്ള ചിത്രങ്ങൾ ഒരു കാരണവശാലും ഇല്ലാതാക്കുകയോ നീക്കുകയോ മാറ്റുകയോ ചെയ്യില്ല. ഇവിടെ External ആശ്രയിക്കുന്നതിന് മുൻപ് Storage-ന് കീഴിൽ ഒരു പ്രൊവൈഡർ കണക്ട് ചെയ്യുക.',

  'set.backup': 'ബാക്കപ്പ്',
  'set.backupTitle': 'ബാക്കപ്പ് സെറ്റിംഗ്സ്',
  'set.backupSub': 'ബാക്കപ്പുകൾ എത്ര നാൾ സൂക്ഷിക്കും, എത്ര സ്റ്റോറേജ് ഉപയോഗിക്കാം.',
  'set.backupRetention': 'ബാക്കപ്പ് നിലനിർത്തൽ',
  'set.backupRetentionMonth': '{count} മാസം',
  'set.backupRetentionMonths': '{count} മാസങ്ങൾ',
  'set.backupMaxStorage': 'പരമാവധി ബാക്കപ്പ് സ്റ്റോറേജ്',
  'set.backupMaxStorageUnit': 'യൂണിറ്റ്',
  'set.backupNote': 'നിലനിർത്തൽ പരിധിയേക്കാൾ പഴയ മാസിക ബാക്കപ്പുകൾ സ്വയമേവ നീക്കം ചെയ്യും. മൊത്തം സ്റ്റോറേജ് പരിധി കടന്നാൽ, ഏറ്റവും പഴയ യോഗ്യമായ ദിവസേനയുള്ള ബാക്കപ്പുകൾ ആദ്യം നീക്കും — ഏറ്റവും പുതിയ ബാക്കപ്പും ഈ മാസത്തെ ബാക്കപ്പ് നിർമ്മിക്കാൻ ഇപ്പോഴും ആവശ്യമുള്ളതും ഒരിക്കലും തൊടില്ല.',

  'set.webhooksSub': 'എന്തെങ്കിലും സംഭവിക്കുന്ന നിമിഷം മറ്റ് ടൂളുകൾക്ക് ഒരു സന്ദേശം അയയ്ക്കുക — ഡെവലപ്പർ ആവശ്യമില്ല',
  'set.webhooksIntro': 'ഒരു ഇമെയിൽ അയക്കുമ്പോഴോ, തുറക്കുമ്പോഴോ, ക്ലിക്ക് ചെയ്യുമ്പോഴോ, ആരെങ്കിലും അൺസബ്സ്ക്രൈബ് ചെയ്യുമ്പോഴോ, {app}-ന് നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന ഒരു വെബ് വിലാസത്തിലേക്ക്, അത് സംഭവിക്കുന്ന അതേ നിമിഷം, ഒരു ചെറിയ സന്ദേശം അയക്കാം.',
  'set.webhooksNoCodeTitle': 'ഏറ്റവും എളുപ്പമുള്ള വഴി — കോഡിംഗ് ഒട്ടും ഇല്ല:',
  'set.webhooksNoCodeText': 'Zapier, Make.com അല്ലെങ്കിൽ Pabbly Connect തുറന്ന്, ഒരു പുതിയ ഓട്ടോമേഷൻ തുടങ്ങി, "Webhooks" അല്ലെങ്കിൽ "Catch Hook" എന്ന ട്രിഗർ തിരഞ്ഞെടുക്കുക. ഇത് നിങ്ങൾക്ക് ഒരു വെബ് വിലാസം നൽകും — ആ വിലാസം താഴെ പേസ്റ്റ് ചെയ്ത്, ഇത് ഓണാക്കി, Save അമർത്തുക. അത്രയേ വേണ്ടൂ.',
  'set.webhookUrlLabel': 'നിങ്ങളുടെ വെബ്‌ഹുക്ക് വിലാസം',
  'set.webhookUrlPlaceholder': 'https://hooks.zapier.com/...',
  'set.webhookEnabledTitle': 'ഈ വിലാസത്തിലേക്ക് ഇവന്റുകൾ അയയ്ക്കുക',
  'set.webhookEnabledDesc': 'നിങ്ങൾ ടൈപ്പ് ചെയ്ത വിലാസം നഷ്ടപ്പെടാതെ, അയയ്ക്കൽ നിർത്താൻ എപ്പോൾ വേണമെങ്കിലും ഇത് ഓഫ് ചെയ്യുക.',
  'set.webhookSecretTitle': 'സൈനിംഗ് സീക്രട്ട്',
  'set.webhookSecretDesc': 'ഒരു സന്ദേശം ശരിക്കും {app}-ൽ നിന്നാണോ എന്ന് നിങ്ങൾ (അല്ലെങ്കിൽ നിങ്ങളുടെ ഡെവലപ്പർ) വീണ്ടും പരിശോധിക്കാൻ ആഗ്രഹിക്കുമ്പോൾ മാത്രം ആവശ്യമുള്ളതാണ്. Zapier പോലുള്ള ടൂളുകൾക്ക് ഇത് ആവശ്യമില്ല — അവ ഇത് കൂടാതെയും പ്രവർത്തിക്കും.',
  'set.webhookSecretNotSet': 'ഇതുവരെ ഒരു സീക്രട്ടും ഉണ്ടാക്കിയിട്ടില്ല',
  'set.generateSecret': 'സീക്രട്ട് ഉണ്ടാക്കുക',
  'set.rotateSecret': 'ഒരു പുതിയതുമായി മാറ്റിസ്ഥാപിക്കുക',
  'set.rotateSecretConfirmTitle': 'സൈനിംഗ് സീക്രട്ട് മാറ്റിസ്ഥാപിക്കണോ?',
  'set.rotateSecretConfirmText': 'നിങ്ങളോ ഒരു ഡെവലപ്പറോ സ്വീകരിക്കുന്ന ഭാഗത്ത് ഈ സീക്രട്ട് പരിശോധിക്കുന്നുണ്ടെങ്കിൽ, അവിടെയും അപ്ഡേറ്റ് ചെയ്യുന്നതുവരെ ആ പരിശോധന പരാജയപ്പെടാൻ തുടങ്ങും. Zapier പോലുള്ള ടൂളുകളെ ഇത് ബാധിക്കില്ല.',
