  'set.webhookSecretOnceWarning': 'ഈ സീക്രട്ട് ഒരു തവണ മാത്രമേ കാണിക്കൂ. ആവശ്യമെങ്കിൽ ഇപ്പോൾ കോപ്പി ചെയ്യുക — {app} പ്ലെയിൻ വില സൂക്ഷിക്കുന്നില്ല, അതിന്റെ ഒരു ഹാഷ് മാത്രം.',
