  'set.apiDocsNote': 'ബാക്കെൻഡ് പ്രവർത്തിക്കുമ്പോൾ OpenAPI/Swagger സഹിതം പൂർണ്ണ REST ഡോക്യുമെന്റേഷൻ /api/docs-ൽ പ്രസിദ്ധീകരിക്കും.',
  'set.apiNotAvailable': 'ഈ വർക്ക്സ്പേസിന് ഇതുവരെ API ആക്സസ് സെറ്റ് ചെയ്തിട്ടില്ല.',
  'set.apiNotAvailableText': 'ഇന്ന് {app}-ൽ ഒരു എക്സ്റ്റേണൽ API കീയോ വെബ്‌ഹുക്ക് സിസ്റ്റമോ ഇല്ല — ഇവിടെ ഉണ്ടായിരുന്ന ബോക്സ്, ഒരിക്കലും ശരിക്കും പ്രവർത്തിക്കാത്ത ഒരു വ്യാജ കീ കാണിച്ചിരുന്നു. ഒരു യഥാർത്ഥത് വേണമെങ്കിൽ ചോദിക്കുക.',

