  'con.suppressionTitle': 'സപ്രഷൻ ലിസ്റ്റ്',
  'con.suppressionSub': 'ഏത് ലിസ്റ്റിൽ കണ്ടാലും ഞങ്ങൾ ഒരിക്കലും ഇമെയിൽ ചെയ്യാത്ത ആളുകൾ',
  'con.suppressionNote': '{unsubscribed} കോൺടാക്റ്റുകൾ അൺസബ്സ്ക്രൈബ് ചെയ്തു, {bounced} വിലാസങ്ങൾ ബൗൺസ് ആയി, ഇവ സപ്രഷൻ ലിസ്റ്റിലാണ്. ഇവ ഓരോ ക്യാമ്പെയ്‌നിൽ നിന്നും സ്വയമേവ നീക്കം ചെയ്യപ്പെടും — നിങ്ങൾ അവയെ ഓർത്തിരിക്കേണ്ടതില്ല.',
