  'seg.subtitle': 'മുൻ ക്യാമ്പെയ്‌നുകളിൽ ആളുകൾ ചെയ്തതിൽ നിന്ന് നിർമ്മിച്ച വീണ്ടും ഉപയോഗിക്കാവുന്ന ലിസ്റ്റുകൾ.',
  'seg.new': 'പുതിയ സെഗ്മെന്റ്',
  'seg.autoNote': 'ഒരു സെഗ്മെന്റ് സ്വയം അപ്ഡേറ്റ് ആകും. ആരെങ്കിലും നാളെ തുറന്നാൽ, അവർ സ്വയമേവ "Interested Leads"-ൽ ചേരും — ലിസ്റ്റ് നിങ്ങൾ ഒരിക്കലും കൈകൊണ്ട് വീണ്ടും ഉണ്ടാക്കേണ്ടതില്ല.',
  'seg.contacts': 'കോൺടാക്റ്റുകൾ',
