  'seg.automationSub': 'സുരക്ഷിതമായ, ഒറ്റ-ക്ലിക്ക് രണ്ട് ഫോളോ-അപ്പുകൾ',
  'seg.resendDesc': 'ഓപ്പൺ രേഖപ്പെടുത്താത്ത എല്ലാവർക്കുമായി ഒരു പുതിയ ക്യാമ്പെയ്ൻ ഉണ്ടാക്കുന്നു. എന്തെങ്കിലും ഉണ്ടാക്കുന്നതിന് മുൻപ് ഞങ്ങൾ കൃത്യമായ എണ്ണം കാണിക്കുകയും സ്ഥിരീകരണം ചോദിക്കുകയും ചെയ്യും.',
