  'seg.followClickedDesc': 'ട്രാക്ക് ചെയ്ത ഒരു ലിങ്ക് ക്ലിക്ക് ചെയ്ത ആളുകളെ ലക്ഷ്യമിടുന്നു — നിങ്ങളുടെ ഏറ്റവും ചൂടേറിയ ലീഡുകൾ. ഇതും ആദ്യം സ്ഥിരീകരണം ചോദിക്കുന്നു.',
