  'camp.openEstimate': '"Open detected" ഒരു ഏകദേശക്കണക്കാണ്.',
  'camp.openEstimateText': 'ട്രാക്കിംഗ് ചിത്രം ലോഡ് ആയി എന്നാണ് ഇതിന്റെ അർത്ഥം — ഒരാൾ ഇമെയിൽ തീർച്ചയായും വായിച്ചു എന്നല്ല. Apple Mail Privacy Protection പോലുള്ള ഫീച്ചറുകൾ ചിത്രങ്ങൾ സ്വയമേവ ലോഡ് ചെയ്യുന്നു, ചിത്ര തടയൽ യഥാർത്ഥ ഓപ്പണുകൾ മറയ്ക്കുന്നു.',
  'camp.sentMeaning': '"Sent" എന്നാൽ വിജയകരമായി കൈമാറി എന്നാണ്.',
  'camp.sentMeaningText': 'നിങ്ങളുടെ ഇമെയിൽ സെർവർ ഡെലിവറിക്ക് സന്ദേശം സ്വീകരിച്ചു എന്നാണ് ഇതിന്റെ അർത്ഥം — ഇൻബോക്സിൽ എത്തി എന്നല്ല. ആരെങ്കിലും അത് ഒരിക്കലും ലഭിച്ചില്ല എന്ന് പറഞ്ഞാൽ, ആദ്യം അവരുടെ Spam ഫോൾഡർ പരിശോധിക്കുക, പിന്നെ നിങ്ങളുടെ ഇമെയിൽ പ്രൊവൈഡറുമായി നിങ്ങളുടെ അയക്കുന്ന ഡൊമെയ്‌നിന്റെ SPF/DKIM സെറ്റപ്പ്.',

